<?php
namespace App\Http\Controllers\Api\V1;
use App\AuditEventType; use App\Http\Controllers\Controller; use App\Http\Requests\Api\V1\StoreReconciliationRequest; use App\Http\Requests\Api\V1\UpdateReconciliationDifferenceRequest; use App\Http\Resources\Api\V1\ReconciliationDifferenceResource; use App\Http\Resources\Api\V1\ReconciliationRunResource; use App\Models\Asset; use App\Models\ReconciliationDifference; use App\Models\ReconciliationRun; use App\Services\AuditLogger; use Illuminate\Http\Resources\Json\AnonymousResourceCollection; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Gate; use Illuminate\Support\Facades\Storage; use Illuminate\Validation\ValidationException;
class ReconciliationController extends Controller {
    public function index(): AnonymousResourceCollection { Gate::authorize('viewAny', ReconciliationRun::class); $runs=ReconciliationRun::with('area')->latest('executed_at')->paginate(25); $runs->getCollection()->transform(fn($r)=>$this->stats($r)); return ReconciliationRunResource::collection($runs); }
    public function show(ReconciliationRun $reconciliation): ReconciliationRunResource { Gate::authorize('view',$reconciliation); return new ReconciliationRunResource($this->stats($reconciliation->load('area')->load('differences.asset'))); }
    public function differences(ReconciliationRun $reconciliation): AnonymousResourceCollection { Gate::authorize('view',$reconciliation); return ReconciliationDifferenceResource::collection($reconciliation->differences()->with('asset')->latest()->paginate(100)); }
    public function store(StoreReconciliationRequest $request, AuditLogger $audit): ReconciliationRunResource {
        $file=$request->file('file'); $rows=$this->readCsv($file->getRealPath()); $codes=[]; foreach($rows as $row){$code=trim((string)($row['asset_code']??$row['codigo_patrimonial']??'')); if($code==='') continue; if(isset($codes[$code])) $codes[$code][]=$row; else $codes[$code]=[$row];}
        $run=DB::transaction(function() use($request,$file,$rows,$codes){ $path=$file->store('reconciliations','local'); $run=ReconciliationRun::create(['code'=>$request->string('code')->toString(),'name'=>$request->string('name')->toString(),'area_id'=>$request->integer('area_id')?:null,'inventory_campaign_id'=>$request->integer('inventory_campaign_id')?:null,'source_file_name'=>$file->getClientOriginalName(),'source_path'=>$path,'created_by'=>$request->user()->id,'status'=>'completed','executed_at'=>now(),'notes'=>$request->string('notes')->toString()?:null]); $assets=Asset::with('area','location','status')->where('is_active',true)->when($run->area_id,fn($q)=>$q->where('area_id',$run->area_id))->get()->keyBy('asset_code'); foreach($codes as $code=>$items){ if(count($items)>1){$run->differences()->create(['asset_code'=>$code,'difference_type'=>'duplicate_reference','reference_snapshot'=>$items,'status'=>'pending']); continue;} $row=$items[0]; $asset=$assets->get($code); if(!$asset){$run->differences()->create(['asset_code'=>$code,'difference_type'=>'missing_in_system','reference_snapshot'=>$row,'status'=>'pending']); continue;} $system=$this->assetSnapshot($asset); $ref=$this->normalizeReference($row); $fields=[]; foreach(['area','location','status'] as $field){if(($ref[$field]??null)!==null && (string)($system[$field]??'')!==(string)$ref[$field]) $fields[]=$field;} foreach($fields as $field){$run->differences()->create(['asset_id'=>$asset->id,'asset_code'=>$code,'difference_type'=>$field.'_mismatch','system_snapshot'=>$system,'reference_snapshot'=>$ref,'status'=>'pending']);} } foreach($assets as $code=>$asset){if(!isset($codes[$code])) $run->differences()->create(['asset_id'=>$asset->id,'asset_code'=>$code,'difference_type'=>'missing_in_reference','system_snapshot'=>$this->assetSnapshot($asset),'status'=>'pending']);} return $run; }); $audit->record(AuditEventType::ReconciliationCreated,$request->user(),$run,['source_file_name'=>$run->source_file_name],$run->area); return new ReconciliationRunResource($this->stats($run->load('area'))); }
    public function updateDifference(UpdateReconciliationDifferenceRequest $request, ReconciliationDifference $difference, AuditLogger $audit): ReconciliationDifferenceResource { $run=$difference->run; Gate::authorize('view',$run); $difference->update(['status'=>$request->string('status')->toString(),'resolution_notes'=>$request->string('resolution_notes')->toString()?:null,'reviewed_by'=>$request->user()->id,'reviewed_at'=>now()]); $audit->record(AuditEventType::ReconciliationDifferenceUpdated,$request->user(),$difference,['status'=>$difference->status],$run->area); return new ReconciliationDifferenceResource($difference->load('asset')); }
    private function stats(ReconciliationRun $run): ReconciliationRun { $run->setAttribute('total_differences',$run->differences()->count()); $run->setAttribute('pending_differences',$run->differences()->whereIn('status',['pending','in_review','pending_external'])->count()); $run->setAttribute('resolved_differences',$run->differences()->where('status','resolved')->count()); return $run; }
    private function readCsv(string $path): array { $h=fopen($path,'rb'); if(!$h) throw ValidationException::withMessages(['file'=>'No se pudo leer el CSV.']); $headers=fgetcsv($h); if(!$headers) throw ValidationException::withMessages(['file'=>'El CSV no contiene encabezado.']); $headers=array_map(fn($v)=>strtolower(trim((string)$v)), $headers); $rows=[]; while(($line=fgetcsv($h))!==false){if(count(array_filter($line,fn($v)=>trim((string)$v)!==''))===0) continue; $rows[]=array_combine(array_pad($headers,count($line),null),array_pad($line,count($headers),null));} fclose($h); return $rows; }
    private function normalizeReference(array $row): array { return ['description'=>$row['description']??$row['descripcion']??null,'area'=>$row['area']??null,'location'=>$row['location']??$row['ubicacion']??null,'status'=>$row['status']??$row['estado']??null]; }
    private function assetSnapshot(Asset $a): array { return ['asset_code'=>$a->asset_code,'description'=>$a->name,'area'=>$a->area?->code,'location'=>$a->location?->code,'status'=>$a->status?->code]; }
}
